UPDATE job_execution
SET status = #{status}, message = #{message}, result_json = CAST(#{resultJson} AS JSON), error_type = #{errorType}, error_message = #{errorMessage}, finished_at = #{finishedAt}, duration_millis = #{durationMillis}
WHERE id = #{id}

UPDATE job_execution
SET status = #{status}, message = #{message}, result_json = CAST(#{resultJson} AS JSON), error_type = #{errorType}, error_message = #{errorMessage}, finished_at = #{finishedAt}, duration_millis = #{durationMillis}
WHERE id = #{id} AND status = #{runningStatus}

UPDATE job_execution
SET status = #{cancelledStatus}, message = #{message}, result_json = CAST('{}' AS JSON), error_type = #{errorType}, error_message = NULL, finished_at = #{finishedAt}, duration_millis = #{durationMillis}
WHERE id = #{id} AND status = #{runningStatus}

UPDATE job_execution
SET status = #{systemExitStatus}, finished_at = CURRENT_TIMESTAMP(3), message = 'Host restarted while job was running'
WHERE status = #{runningStatus}

